-- Hand-edited: a counted write or a link use is inserted, read and deleted — when it leaves the day
-- (the worker's purge), or to be inserted again under the new number when an operator changes a
-- member's number (docs/OPERATIONS.md) — never rewritten. A review-list entry is inserted, read,
-- marked once by an operator (its `review_action_id`, the only column buddha_app may update) and
-- deleted when its retention period ends (#184, owner decision 2026-10-22). buddha_app keeps the
-- rest of the default privileges in docker/postgres/init/01-roles.sql. A table-level REVOKE also
-- revokes the column privileges, so the column's GRANT comes after it.
REVOKE UPDATE ON TABLE "write_limit_events", "link_uses", "link_flags" FROM buddha_app;--> statement-breakpoint
GRANT UPDATE ("review_action_id") ON TABLE "link_flags" TO buddha_app;--> statement-breakpoint
-- Hand-edited: an entry is marked once. The mark names the operator's admin_actions row (who, when,
-- what came of it), and a second mark would leave that row saying it covered an entry another
-- covers; the app marks only entries with none (`WHERE review_action_id IS NULL`), and this keeps
-- any other UPDATE from moving or clearing a mark. Runs as the invoker. TRUNCATE fires no row
-- trigger.
CREATE FUNCTION link_flags_review_once() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.review_action_id IS NOT NULL THEN
    RAISE EXCEPTION 'link flag % is marked already: its mark never changes', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER link_flags_review_once
  BEFORE UPDATE ON "link_flags"
  FOR EACH ROW EXECUTE FUNCTION link_flags_review_once();
